import{_ as t,a,o,a6 as n}from"./chunks/framework.CJDy2q7X.js";const m=JSON.parse(`{"title":"Get Admin Profile","description":"","frontmatter":{"outline":false,"apiType":"rest","examples":[{"id":"admin-get-profile","title":"Get Admin Profile","description":"Return the authenticated admin's profile. The token identifies the admin, so the endpoint takes no parameters.","query":"curl -X GET \\"https://your-domain.com/api/admin/get\\" \\\\\\n  -H \\"Accept: application/json\\" \\\\\\n  -H \\"Authorization: Bearer <id>|<token>\\"\\n","variables":"{}\\n","response":"[\\n  {\\n    \\"id\\": \\"1\\",\\n    \\"name\\": \\"Example Admin\\",\\n    \\"email\\": \\"admin@example.com\\",\\n    \\"image\\": null,\\n    \\"status\\": \\"1\\",\\n    \\"roleId\\": 1,\\n    \\"roleName\\": \\"Administrator\\",\\n    \\"success\\": true,\\n    \\"message\\": null\\n  }\\n]\\n","commonErrors":[{"error":"Unauthenticated (401)","cause":"Missing, malformed, expired, or revoked Bearer token, or a client IP outside the token's allowlist","solution":"Send a valid admin Bearer token (Integration token) in the Authorization header. See the Authentication page."}]}]},"headers":[],"relativePath":"api/rest-api/admin/profile/get-profile.md","filePath":"api/rest-api/admin/profile/get-profile.md","lastUpdated":1787290888000}`),i={name:"api/rest-api/admin/profile/get-profile.md"};function s(d,e,r,l,h,c){return o(),a("div",null,e[0]||(e[0]=[n(`<h1 id="get-admin-profile" tabindex="-1">Get Admin Profile <a class="header-anchor" href="#get-admin-profile" aria-label="Permalink to &quot;Get Admin Profile&quot;">​</a></h1><p>Returns the profile of the admin who owns the Bearer token on the request. Use it to confirm a token is live and to learn who it belongs to — the account name and email to show in a header, and the role that governs everything else the token can do.</p><h2 id="endpoint" tabindex="-1">Endpoint <a class="header-anchor" href="#endpoint" aria-label="Permalink to &quot;Endpoint&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Endpoint</th><th>Method</th><th>Purpose</th></tr></thead><tbody><tr><td><code>/api/admin/get</code></td><td>GET</td><td>Return the authenticated admin&#39;s profile</td></tr></tbody></table><p>The endpoint takes <strong>no path or query parameters</strong>. The token alone selects the record, so there is no way to read another admin&#39;s profile here — use the <a href="/api/rest-api/admin/settings/users/list.html">Settings → Users</a> endpoints for that.</p><h2 id="response-fields" tabindex="-1">Response Fields <a class="header-anchor" href="#response-fields" aria-label="Permalink to &quot;Response Fields&quot;">​</a></h2><p>The response is a <strong>JSON array holding exactly one object</strong>, not a bare object — read <code>[0]</code>, or destructure the first element.</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>String</td><td>The admin id, as a string.</td></tr><tr><td><code>name</code></td><td>String</td><td>Admin&#39;s display name.</td></tr><tr><td><code>email</code></td><td>String</td><td>Admin&#39;s login email.</td></tr><tr><td><code>image</code></td><td>String</td><td>Storage path of the avatar, or <code>null</code> when none is set.</td></tr><tr><td><code>status</code></td><td>String</td><td><code>&quot;1&quot;</code> when the account is active, <code>&quot;0&quot;</code> when disabled.</td></tr><tr><td><code>roleId</code></td><td>Integer</td><td>Id of the assigned role, or <code>null</code> when the admin has no role.</td></tr><tr><td><code>roleName</code></td><td>String</td><td>Name of the assigned role, or <code>null</code> when the admin has no role.</td></tr><tr><td><code>success</code></td><td>Boolean</td><td>Always <code>true</code>. Present for shape parity across the admin payloads.</td></tr><tr><td><code>message</code></td><td>String</td><td>Always <code>null</code>. Present for shape parity across the admin payloads.</td></tr></tbody></table><p>Three of these behave differently from how they look:</p><ul><li><strong><code>id</code> and <code>status</code> are strings, not numbers.</strong> <code>status</code> is <code>&quot;1&quot;</code> / <code>&quot;0&quot;</code> — compare against the string, or cast before testing, since a bare truthiness check treats <code>&quot;0&quot;</code> as true in most languages.</li><li><strong><code>roleId</code> is an integer</strong> while <code>id</code> beside it is a string. The two are not interchangeable types.</li><li><strong><code>success</code> and <code>message</code> are constants</strong>, not a result signal. A successful call is HTTP <code>200</code>; a failed one never reaches this body. Never branch on them.</li></ul><h2 id="role-fields" tabindex="-1">Role Fields <a class="header-anchor" href="#role-fields" aria-label="Permalink to &quot;Role Fields&quot;">​</a></h2><p><code>roleId</code> and <code>roleName</code> name the role, but they do not tell you what the token may do — a token can be narrowed below its owner&#39;s role. To gate UI, call <a href="/api/rest-api/admin/navigation/permissions.html">Get Admin Permissions</a> instead, which returns the effective permission set after that narrowing.</p><h2 id="errors" tabindex="-1">Errors <a class="header-anchor" href="#errors" aria-label="Permalink to &quot;Errors&quot;">​</a></h2><p>An unauthenticated request is rejected before the endpoint runs. A missing, malformed, expired, or revoked token returns HTTP <code>401</code>:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;message&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Unauthenticated.&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;error&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;unauthenticated&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>No permission check applies — any valid token can read its own profile, whatever its permission mode.</p><h2 id="read-only" tabindex="-1">Read-Only <a class="header-anchor" href="#read-only" aria-label="Permalink to &quot;Read-Only&quot;">​</a></h2><p>There is no write counterpart. The admin API has no login, logout, forgot-password, or profile-update endpoint — accounts are managed in the admin panel, and tokens are issued from the Integration menu. To edit an admin record programmatically, use the <a href="/api/rest-api/admin/settings/users/update.html">Settings → Users</a> endpoints, which act on any admin by id and are permission-gated.</p>`,18)]))}const u=t(i,[["render",s]]);export{m as __pageData,u as default};
